{
  "root": "main_stack",
  "state": {
    "detailed_stock_breakdown_rows": [
      {
        "location_category": "Warehouse A",
        "quantity": 0,
        "notes": "Currently empty"
      },
      {
        "location_category": "Warehouse B",
        "quantity": 5,
        "notes": "Main stock location"
      },
      {
        "location_category": "Store Front",
        "quantity": 2,
        "notes": "Floor units"
      },
      {
        "location_category": "Reserved Units",
        "quantity": -7,
        "notes": "Committed stock"
      },
      {
        "location_category": "Net Available",
        "quantity": 0,
        "notes": "Out of Stock"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title",
        "summary_stack",
        "inventory_context_heading",
        "inventory_context_text",
        "detailed_stock_heading",
        "stock_table",
        "media_section_heading",
        "images_stack",
        "icons_stack",
        "quick_actions_heading",
        "quick_actions_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "SKU #99001 Availability Snapshot",
        "variant": "h2"
      },
      "children": []
    },
    "summary_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "status_icon",
        "summary_text"
      ]
    },
    "status_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_001590_01_4_exclamation-circle.svg"
      },
      "children": []
    },
    "summary_text": {
      "type": "Text",
      "props": {
        "text": "Based on the current inventory data, the Blue Widget (SKU #99001) has 0 units available for sale. Although there is a total physical count of 7 units across your warehouses and store front, the 7 reserved units fully offset this stock. Consequently, the item is effectively out of stock for new orders until replenishment occurs or reservations are released.",
        "variant": "body"
      },
      "children": []
    },
    "inventory_context_heading": {
      "type": "Text",
      "props": {
        "text": "Inventory Calculation Context",
        "variant": "h3"
      },
      "children": []
    },
    "inventory_context_text": {
      "type": "Text",
      "props": {
        "text": "The Available for Sale status is derived by summing the physical inventory from all listed locations (Warehouse A, Warehouse B, and Store Front) and subtracting the Reserved quantity. Reserved items are considered committed to existing orders or transfers and are therefore excluded from sellable inventory.",
        "variant": "body"
      },
      "children": []
    },
    "detailed_stock_heading": {
      "type": "Text",
      "props": {
        "text": "Detailed Stock Breakdown",
        "variant": "h3"
      },
      "children": []
    },
    "stock_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "location_category",
            "label": "Location / Category"
          },
          {
            "key": "quantity",
            "label": "Quantity"
          },
          {
            "key": "notes",
            "label": "Notes"
          }
        ],
        "statePath": "/detailed_stock_breakdown_rows",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "media_section_heading": {
      "type": "Text",
      "props": {
        "text": "Related Visuals",
        "variant": "h3"
      },
      "children": []
    },
    "images_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "warehouse_image",
        "product_image"
      ]
    },
    "warehouse_image": {
      "type": "Image",
      "props": {
        "url": "../assets/r_001590_01_1_warehouse_shelves.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "product_image": {
      "type": "Image",
      "props": {
        "url": "../assets/r_001590_01_2_blue_product.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "icons_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "inventory_box_icon_row",
        "status_alert_icon_row",
        "bell_icon_row",
        "calculator_icon_row"
      ]
    },
    "inventory_box_icon_row": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "inventory_box_icon",
        "inventory_box_text"
      ]
    },
    "inventory_box_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_001590_01_3_box-seam.svg"
      },
      "children": []
    },
    "inventory_box_text": {
      "type": "Text",
      "props": {
        "text": "Inventory Box",
        "variant": "body"
      },
      "children": []
    },
    "status_alert_icon_row": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "status_alert_icon",
        "status_alert_text"
      ]
    },
    "status_alert_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_001590_01_4_exclamation-circle.svg"
      },
      "children": []
    },
    "status_alert_text": {
      "type": "Text",
      "props": {
        "text": "Status Alert",
        "variant": "body"
      },
      "children": []
    },
    "bell_icon_row": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "bell_icon",
        "bell_text"
      ]
    },
    "bell_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_001374_01_1_calculator.svg"
      },
      "children": []
    },
    "bell_text": {
      "type": "Text",
      "props": {
        "text": "Bell",
        "variant": "body"
      },
      "children": []
    },
    "calculator_icon_row": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "calculator_icon",
        "calculator_text"
      ]
    },
    "calculator_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_001590_01_6_bell.svg"
      },
      "children": []
    },
    "calculator_text": {
      "type": "Text",
      "props": {
        "text": "Calculator",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "search_suppliers_button",
        "inventory_tips_button"
      ]
    },
    "search_suppliers_button": {
      "type": "Button",
      "props": {
        "label": "Search Suppliers"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/search?q=blue+widget+wholesale+suppliers"
          }
        }
      },
      "children": []
    },
    "inventory_tips_button": {
      "type": "Button",
      "props": {
        "label": "Inventory Management Tips"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.investopedia.com/terms/i/inventory-management.asp"
          }
        }
      },
      "children": []
    }
  }
}
